/* The provider ABI: the coupler drives a plugin through this table. Every
 * member has the shape
 *     fuse_status f(fuse_provider_ctx* self, const IN* in, OUT* out);
 * `self` is the plugin's own per-instance handle (create()'s own output),
 * a DIFFERENT opaque type from the participant table's fuse_ctx* (types.h),
 * so the two tables' handles cannot be confused at the call site even
 * though both are plain pointers to the compiler. `in` and `out` are the
 * argument structs of types.h, shared with the participant table where they
 * fit (fuse_field_view, fuse_step_request/fuse_step_report); pass NULL where
 * the type is fuse_null. The table itself begins with struct_size: a caller
 * compares it with sizeof(fuse_provider_abi_v1) and uses only the members
 * that are present, so a v1 host runs a later plugin's v1 subset. */
typedef struct fuse_provider_abi_v1 {
  uint32_t struct_size;
  uint32_t abi_version;

  /* self may be NULL; the plugin's own library version */
  fuse_status (*version)(fuse_provider_ctx* self, const fuse_null* in, fuse_version_info* out);

  /* self must be NULL */
  fuse_status (*create)(fuse_provider_ctx* self, const fuse_null* in, fuse_provider_instance* out);

  /* a double destroy is FUSE_ERR_INVALID, not a crash */
  fuse_status (*destroy)(fuse_provider_ctx* self, const fuse_null* in, fuse_null* out);

  /* after create, before bind; the fields this instance provides and/or */
  /* requires */
  fuse_status (*describe)(fuse_provider_ctx* self, const fuse_null* in, fuse_field_table* out);

  /* before the first advance; once per field describe() reported; the pointer */
  /* must stay valid until destroy */
  fuse_status (*bind)(fuse_provider_ctx* self, const fuse_field_view* in, fuse_null* out);

  /* integrate from in->t_begin to in->t_end; out echoes the window actually */
  /* run, exactly (rule 6) */
  fuse_status (*advance)(fuse_provider_ctx* self, const fuse_step_request* in, fuse_step_report* out);

  /* checkpoint the state advance() mutates, so the same interval can be */
  /* re-advanced; only one checkpoint need be retained */
  fuse_status (*save_state)(fuse_provider_ctx* self, const fuse_null* in, fuse_null* out);

  /* restore the state captured by the most recent successful save_state() */
  fuse_status (*restore_state)(fuse_provider_ctx* self, const fuse_null* in, fuse_null* out);

  /* self may be NULL; FUSE_CAP_CHECKPOINT means save_state/restore_state are */
  /* real, not the default no-op */
  fuse_status (*capabilities)(fuse_provider_ctx* self, const fuse_null* in, fuse_capability_set* out);

  /* an opaque, versioned byte record capturing whatever save_state()'s */
  /* in-memory rollback cannot reach (component-private state outside */
  /* register_fields()' own storage). Same-decomposition restore only: the */
  /* rank-count refusal that gates this happens above this ABI boundary, in */
  /* fuse::check_restart_rank_count(). FUSE_CAP_CHECKPOINT has no bearing on */
  /* this entry; a provider not implementing it reports written=0 and */
  /* blob_version=0, which the caller treats as nothing to capture, not as an */
  /* error, exactly as the C++ Component::save_restart_blob() default does */
  fuse_status (*save_restart_blob)(fuse_provider_ctx* self, const fuse_null* in, fuse_restart_blob_sink* out);

  /* the read-back counterpart of save_restart_blob(); FUSE_ERR_VERSION (not a */
  /* silent misread) if blob_version names a version this build does not */
  /* recognise, the same posture kGraphVersion takes for the coupling graph */
  /* (fuse/model/descriptor.hpp) */
  fuse_status (*load_restart_blob)(fuse_provider_ctx* self, const fuse_restart_blob_source* in, fuse_null* out);
} fuse_provider_abi_v1;

/* THE ONE EXPORTED SYMBOL A PLUGIN PROVIDES. Returns the table for
 * `abi_version`, or NULL when the plugin does not speak that version.
 * Static storage inside the plugin; never freed. Thread-safe. Several
 * plugins, each its own shared object, may each export this same name --
 * fuse::Registry resolves it through each object's own dlopen() handle
 * (docs/dev/abi-design.md, point 4), never through the global symbol
 * table, so two plugins exporting it is not a collision. */
const fuse_provider_abi_v1* fuse_provider_abi(uint32_t abi_version);

